                    }
                    .into());
                }
            };

            let allow_credit_cards = get_google_pay_card_type_restrictions(wallet_blocking_config);

            let gpay_allowed_payment_methods = gpay_data
                .allowed_payment_methods
                .into_iter()
                .map(
